/**
 * One-shot rig. Prints the per-character advance tables the app does its width arithmetic from, so
 * `labels.ts` and `fit.ts` are regenerated by measurement rather than by hand. Not run in CI — it
 * needs a browser, and the tables it produces are committed constants
 * (docs/app.md §Columns and sorting, §Two renderings, and only one of them mounted).
 *
 * Run from the repo root: node app/scripts/measure-label-widths.mjs
 *
 * A table is specific to a FACE, a SIZE, a WEIGHT and a TRACKING — all four. Each block below names
 * the code site it feeds and the CSS rule it was read off; change either and the numbers stop being
 * true. The sizes are the rem tokens resolved against a 16px root: `--t-xs` 0.75rem is 12px and
 * `--t-md` 0.92rem is 14.72px.
 */
import { chromium, firefox, webkit } from 'playwright';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const font = (name) => readFileSync(join(here, `../src/assets/fonts/${name}`)).toString('base64');
const ui = font('inter-tight.woff2');
const mono = font('jetbrains-mono.woff2');

/**
 * The phone header's set. Kept as it was: the table it feeds is validated against a 48px bound, so
 * a wider set would only add characters no short label uses.
 */
const PHONE_CHARS = [...'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 .,/()%-Δ'];
/**
 * The desktop set is wider because the strings it measures are the fleet's own, not a curated label
 * list: upstream test names, categorical option names ("Both sides (semi)"), plate words, dates and
 * shoe names. Taken from the real dataset's own character census plus the punctuation the app adds
 * — `£` and `/` for units, `—` for an absent reading, `:` from "Tongue: gusset type".
 */
const DESKTOP_CHARS = [...'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 .,:;/()%+-£—Δ'];
/**
 * A units string is a different alphabet from a name or a phrase, which is why it gets its own set
 * rather than borrowing `DESKTOP_CHARS`: it is `test.units` straight from upstream (`HC`, `HA`,
 * `SA`, `AC`, `BR`, `Nm`, `mm`, `g`, `N`, `°`) plus the five the app derives (`%`, `/5`, `/100`,
 * `£`, and `size-rating`'s override). `°` and `=` appear nowhere else and were missing from the
 * census the units tables were first taken over — `rocker` ships `°` today.
 */
const UNITS_CHARS = [...'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 ./%=£°'];

/**
 * `take` names which engine's measurements a consumer commits to, and every table below takes
 * **chromium** — the same choice `labels.ts` has always made.
 *
 * `max`, the per-character maximum over every engine swept, was tried for the fit tables and
 * rejected by measurement: the engines disagree by at most 0.51px on any character and by ~2px on a
 * whole column set, but a per-character maximum SUMS disagreements that never co-occur in one
 * engine, which put the model 8–15px over the width every engine actually rendered. One engine's
 * table plus a slack wide enough for the measured spread is the sharper instrument, and
 * `cross-browser.spec.ts` is what keeps the spread honest in all three.
 *
 * It is still printed per engine below, so the spread is visible when the face changes.
 */
const FACES = [
  {
    name: 'CHAR_PX (app/src/lib/labels.ts)',
    css: "font-family:M,system-ui;font-size:12px;font-weight:600;letter-spacing:-0.02em",
    note: 'phone header — Inter Tight 600 at 12px, -0.02em (ShoeTableMobile.svelte th button)',
    chars: PHONE_CHARS, take: 'chromium',
  },
  {
    name: 'HEADER_PX (app/src/lib/fit.ts)',
    css: "font-family:M,system-ui;font-size:14.72px;font-weight:600;letter-spacing:normal",
    note: 'desktop header — Inter Tight 600 at 14.72px (--t-md), no tracking (ShoeTable.svelte th button)',
    chars: DESKTOP_CHARS, take: 'chromium',
  },
  {
    name: 'NAME_PX (app/src/lib/fit.ts)',
    css: "font-family:M,system-ui;font-size:14.72px;font-weight:700;letter-spacing:normal",
    note: 'desktop shoe name — Inter Tight 700 at 14.72px, no tracking (ShoeTable.svelte td.name strong, whose weight is the UA default for <strong> against a 400 parent and is read back, not assumed, by .hunt/max-content.ts)',
    chars: DESKTOP_CHARS, take: 'chromium',
  },
  {
    name: 'PHRASE_PX (app/src/lib/fit.ts)',
    css: "font-family:M,system-ui;font-size:14.72px;font-weight:400;letter-spacing:normal",
    note: 'desktop phrase cell — Inter Tight 400 at 14.72px, no tracking (ShoeTable.svelte td.num:not(.fig))',
    chars: DESKTOP_CHARS, take: 'chromium',
  },
  {
    name: 'FIGURE_ADVANCE_PX (app/src/lib/fit.ts)',
    css: "font-family:J,ui-monospace;font-size:14.72px;font-weight:400;letter-spacing:-0.02em",
    note: 'desktop figure cell — JetBrains Mono 400 at 14.72px, -0.02em (ShoeTable.svelte td.fig)',
    chars: DESKTOP_CHARS, take: 'chromium',
  },
  {
    name: 'UNITS_ADVANCE_PX (app/src/lib/fit.ts)',
    css: "font-family:J,ui-monospace;font-size:12px;font-weight:400;letter-spacing:normal",
    note: 'desktop units line — JetBrains Mono 400 at 12px (--t-xs), no tracking (ShoeTable.svelte .h-units)',
    chars: UNITS_CHARS, take: 'chromium',
  },
  {
    name: 'UNITS_CHAR_PX (app/src/lib/labels.ts)',
    css: "font-family:J,ui-monospace;font-size:12px;font-weight:400;letter-spacing:-0.02em",
    note: 'phone units line — JetBrains Mono 400 at 12px (--t-xs), -0.02em (ShoeTableMobile.svelte .h-units, which sets neither size nor tracking and inherits both from the th button)',
    chars: UNITS_CHARS, take: 'chromium',
  },
];

const ENGINES = { chromium, firefox, webkit };
// WebKit cannot launch on this host (docs/operations.md §The e2e run needs three browsers); run it
// through `sh hunt/in-docker.sh app/scripts/measure-label-widths.mjs chromium,firefox,webkit`.
const engines = (process.argv[2] ?? 'chromium,firefox').split(',');

const measured = {};
for (const engine of engines) {
  const browser = await ENGINES[engine].launch();
  const page = await browser.newPage();
  await page.setContent('<body></body>');
  measured[engine] = await page.evaluate(async ({ ui, mono, faces }) => {
    for (const [family, b64, weights] of [['M', ui, '400 700'], ['J', mono, '400 600']]) {
      const face = new FontFace(family, `url(data:font/woff2;base64,${b64}) format('woff2-variations')`,
        { weight: weights });
      await face.load();
      document.fonts.add(face);
    }
    const s = document.createElement('span');
    document.body.appendChild(s);
    return faces.map((face) => {
      // `M, system-ui` and `J, ui-monospace`, not the shipped family alone: both files are LATIN
      // subsets, so `Δ` (U+0394) and `—` (U+2014) can fall through to the next family in the stack —
      // and the stack has to be the app's own (`--font-ui`, `--font-mono`) rather than the headless
      // default, or a fallen-back glyph is measured against the wrong face.
      s.style.cssText = `position:absolute;white-space:pre;${face.css}`;
      const table = {};
      for (const ch of face.chars) {
        // 20 repeats then divide: a single glyph rounds badly at these sizes.
        s.textContent = ch.repeat(20);
        table[ch] = +(s.getBoundingClientRect().width / 20).toFixed(2);
      }
      return table;
    });
  }, { ui, mono, faces: FACES });
  await browser.close();
}

/**
 * The desktop name cell's fixed FURNITURE — the chevron and the whole discontinued chip — which is
 * everything in that cell other than the shoe's own name. Both are single, fixed strings rather than
 * alphabets, so `fit.ts` states each as one measured token; a per-character table for either would
 * have a single row of interest.
 *
 * The chip's markup and its rule are read out of `DiscontinuedTag.svelte` rather than copied, so the
 * word and the box cannot drift from the component. Only the TOKENS the rule names are transcribed
 * (`--s1`, `--s2`, `--t-xs`, `--r-sm` from `app.css`), because a `var()` this page cannot resolve
 * would drop the whole declaration and silently measure a chip with no border. What is reported is
 * the chip's OUTER width, its left margin included: that margin is the gap between the name and the
 * chip and belongs to the same token (docs/app.md §Table presentation).
 */
const DISC_TAG = readFileSync(join(here, '../src/components/DiscontinuedTag.svelte'), 'utf8');
const DISC_WORD = DISC_TAG.match(/<span class="disc-tag">([^<]*)<\/span>/)[1];
const DISC_RULE = DISC_TAG.match(/\.disc-tag \{([\s\S]*?)\}/)[1]
  .replace(/var\(--s1\)/g, '4px').replace(/var\(--s2\)/g, '8px')
  .replace(/var\(--t-xs\)/g, '12px').replace(/var\(--r-sm\)/g, '4px')
  // Colour tokens do not move a width, but an unresolved `var()` invalidates the declaration that
  // carries it — and `border` is one of them, which is 2px of chip.
  .replace(/var\(--text-dim\)/g, '#000').replace(/var\(--border\)/g, '#000');

const furniture = {};
for (const engine of engines) {
  const browser = await ENGINES[engine].launch();
  const page = await browser.newPage();
  await page.setContent('<body></body>');
  furniture[engine] = await page.evaluate(async ({ ui, word, rule }) => {
    const face = new FontFace('M', `url(data:font/woff2;base64,${ui}) format('woff2-variations')`,
      { weight: '400 700' });
    await face.load();
    document.fonts.add(face);
    // The cell's own face and size (`ShoeTable.svelte`, `table { font-size: var(--t-md) }` against
    // `--font-ui`), which both the chevron and the chip inherit.
    document.body.style.cssText = 'margin:0;font-family:M,system-ui;font-size:14.72px';
    document.body.innerHTML = `<span id="c" style="display:inline-block">›</span>`
      + `<span id="t" style="${rule}">${word}</span>`;
    const outer = (el) => {
      const s = getComputedStyle(el);
      return el.getBoundingClientRect().width + parseFloat(s.marginLeft) + parseFloat(s.marginRight);
    };
    return {
      chevPx: +document.getElementById('c').getBoundingClientRect().width.toFixed(2),
      discTagPx: +outer(document.getElementById('t')).toFixed(2),
    };
  }, { ui, word: DISC_WORD, rule: DISC_RULE });
  await browser.close();
}

/**
 * The phone header's corner caret, and the one block here that measures INK rather than advance.
 * The mark is out of flow in the cell's bottom-right corner and lands ON the unit line, so the
 * budget the centred string actually has is not the column's text width but the gap to the mark's
 * leftmost painted pixel — which is neither the caret's box (12px of which 3.7 is air) nor the
 * path's own bounding rect (the engines disagree about whether that includes the stroke, and both
 * disagree with what is painted by about 0.35px). Pixels are the only instrument that answers, and
 * both engines paint the mark in exactly the same place.
 *
 * The SVG is read out of `SortCaret.svelte` rather than copied, so the mark cannot drift from the
 * component. Its PLACEMENT is copied — the `.caret.corner` rule's `right`, the `--caret-w` token
 * and the phone column's 53.33px/2px geometry — and a change to any of those is a change to this
 * block (docs/app.md §Table presentation).
 */
const CARET_SVG = readFileSync(join(here, '../src/components/SortCaret.svelte'), 'utf8')
  .match(/<svg[\s\S]*?<\/svg>/)[0];
const COLUMN_PX = 53.328;   // six columns of a 360px phone, `--table-w` in ShoeTableMobile.svelte
const TH_PAD_PX = 2;        // th padding, deliberately not --s1 (same file)
const CARET_RIGHT_PX = 2;   // .caret.corner's own offset
const CARET_W_PX = 12;      // --caret-w (app.css)
const SHOT_SCALE = 8;

const caret = {};
for (const engine of engines) {
  const browser = await ENGINES[engine].launch();
  const page = await browser.newPage({ deviceScaleFactor: SHOT_SCALE });
  await page.setContent(`<style>
    body { margin: 0; background: #fff; }
    .th { position: relative; box-sizing: border-box; width: ${COLUMN_PX}px; height: 20px;
          padding: 0 ${TH_PAD_PX}px; }
    .caret { position: absolute; right: ${CARET_RIGHT_PX}px; bottom: 4px; display: inline-flex;
             justify-content: flex-end; width: ${CARET_W_PX}px; color: #000; }
  </style><div class="th"><span class="caret">${CARET_SVG}</span></div>`);
  const shot = (await page.locator('.th').screenshot()).toString('base64');
  // Decoded by the browser that took it: a PNG decoder in here would be a second thing to keep
  // right, and `createImageBitmap` is exact.
  caret[engine] = await page.evaluate(async ({ shot, scale, pad }) => {
    const bmp = await createImageBitmap(await (await fetch(`data:image/png;base64,${shot}`)).blob());
    const cv = document.createElement('canvas');
    cv.width = bmp.width; cv.height = bmp.height;
    cv.getContext('2d').drawImage(bmp, 0, 0);
    const d = cv.getContext('2d').getImageData(0, 0, bmp.width, bmp.height).data;
    let min = Infinity, max = -Infinity;
    for (let y = 0; y < bmp.height; y++) {
      for (let x = 0; x < bmp.width; x++) {
        // Any departure from the white ground counts, antialiased edges included: the fringe is
        // what a glyph meets first.
        if (d[(y * bmp.width + x) * 4] > 247) continue;
        if (x < min) min = x;
        if (x > max) max = x;
      }
    }
    const box = document.querySelector('.th').getBoundingClientRect();
    const contentW = box.width - 2 * pad;
    return { contentW, inkLeft: min / scale - pad, inkRight: (max + 1) / scale - pad };
  }, { shot, scale: SHOT_SCALE, pad: TH_PAD_PX });
  await browser.close();
}

FACES.forEach((face, i) => {
  const tables = engines.map((e) => measured[e][i]);
  const merged = Object.fromEntries(face.chars.map((ch) => [ch,
    +Math.max(...tables.map((t) => t[ch])).toFixed(2)]));
  const table = face.take === 'max' ? merged : measured[engines[0]][i];
  const widths = Object.values(table);
  // A fallback stands in for a character the table has never seen, so it must be at least the
  // widest thing measured rather than a leftover from the previous face.
  const fallback = Math.ceil(Math.max(...widths));
  // A monospaced face collapses to one number; this is what says so rather than assuming it. `Δ`
  // is excluded because it is not in the shipped subset — it falls back to a proportional face,
  // and no figure or unit string contains one.
  const mono2 = Object.entries(table).filter(([ch]) => ch !== 'Δ').map(([, w]) => w);
  const uniform = Math.max(...mono2) - Math.min(...mono2) < 0.01 ? mono2[0] : null;
  const spread = face.chars
    .map((ch) => Math.max(...tables.map((t) => t[ch])) - Math.min(...tables.map((t) => t[ch])));

  console.log(`\n/* ${face.name}   [take: ${face.take}, engines: ${engines.join('+')}]`);
  console.log(`   ${face.note}`);
  console.log(`   ${face.css}`);
  console.log(`   widest per-character disagreement between engines: ${Math.max(...spread).toFixed(2)}px */`);
  if (uniform === null) {
    console.log(JSON.stringify(table, null, 0));
    console.log('FALLBACK =', fallback);
  } else {
    console.log(`UNIFORM ADVANCE = ${uniform}  (every character but Δ measures the same)`);
  }
});

console.log(`\n/* CHEV_PX and DISC_TAG_PX (app/src/lib/fit.ts)   [take: ${engines[0]}, engines: ${engines.join('+')}]`);
console.log(`   desktop name cell — the chevron's advance and the whole \`${DISC_WORD}\` chip, its left margin included */`);
for (const engine of engines) {
  console.log(`   ${engine}: chevron ${furniture[engine].chevPx}px, chip ${furniture[engine].discTagPx}px`);
}

const advance = measured[engines[0]][FACES.findIndex((f) => f.name.startsWith('UNITS_CHAR_PX'))].m;
console.log(`\n/* MAX_UNITS_CLEAR_PX (app/src/lib/labels.ts)   [engines: ${engines.join('+')}]`);
console.log(`   phone sort caret — ${CARET_W_PX}px box at right:${CARET_RIGHT_PX}px in a ${COLUMN_PX}px column with ${TH_PAD_PX}px padding */`);
for (const engine of engines) {
  const { contentW, inkLeft, inkRight } = caret[engine];
  // What a centred string may take before its ADVANCE BOX reaches the mark. Its ink stops a side
  // bearing short of that, which is the whole margin the five-character `3=TTS` lives in.
  const clear = 2 * inkLeft - contentW;
  console.log(`   ${engine}: text box ${contentW.toFixed(2)}px; caret ink ${inkLeft.toFixed(2)}..${inkRight.toFixed(2)} from its left edge`);
  console.log(`     mark starts ${(contentW - inkLeft).toFixed(2)}px inside the text box's right edge`);
  console.log(`     centred advance box clears it at <= ${clear.toFixed(2)}px = ${(clear / advance).toFixed(2)} characters`);
  for (const n of [4, 5, 6]) {
    const over = (n * advance - clear) / 2;
    console.log(`     ${n} chars = ${(n * advance).toFixed(2)}px advance, right edge ${over > 0 ? `${over.toFixed(2)}px under the mark` : `${(-over).toFixed(2)}px clear of it`}`);
  }
}
